package com.jnapanam.sportszone.notification.service;
import com.jnapanam.sportszone.common.exception.*;import com.jnapanam.sportszone.identity.model.User;import com.jnapanam.sportszone.identity.repository.UserRepository;import com.jnapanam.sportszone.notification.dto.*;import com.jnapanam.sportszone.notification.model.*;import com.jnapanam.sportszone.notification.repository.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class NotificationService{private final NotificationRepository notifications;private final NotificationPreferenceRepository preferences;private final NotificationTemplateRepository templates;private final UserRepository users;public NotificationService(NotificationRepository n,NotificationPreferenceRepository p,NotificationTemplateRepository t,UserRepository u){notifications=n;preferences=p;templates=t;users=u;}
 @Transactional public void payment(UUID userId,String receipt,long paise){notify(userId,"PAYMENT","Payment successful","Payment "+receipt+" of ₹"+money(paise)+" was successful.");}
 @Transactional public void refund(UUID userId,String receipt,long paise){notify(userId,"REFUND","Refund processed","Refund of ₹"+money(paise)+" for "+receipt+" was processed.");}
 @Transactional public NotificationResponse notify(UUID userId,String category,String subject,String message){User u=user(userId);return NotificationResponse.from(notifications.save(new Notification(u,NotificationChannel.IN_APP,category,subject,message)));}
 @Transactional(readOnly=true)public List<NotificationResponse>mine(UUID userId){return notifications.findByUserIdOrderByCreatedAtDesc(userId).stream().map(NotificationResponse::from).toList();}
 @Transactional public NotificationResponse read(UUID userId,UUID id){Notification n=notifications.findById(id).orElseThrow(()->new NotFoundException("Notification not found"));if(!n.getUser().getId().equals(userId))throw new NotFoundException("Notification not found");n.read();return NotificationResponse.from(n);}
 @Transactional public PreferenceResponse preference(UUID userId){NotificationPreference p=preferences.findById(userId).orElseGet(()->preferences.save(new NotificationPreference(user(userId))));return pref(p);}
 @Transactional public PreferenceResponse preference(UUID userId,PreferenceRequest r){NotificationPreference p=preferences.findById(userId).orElseGet(()->new NotificationPreference(user(userId)));p.update(r.emailEnabled(),r.smsEnabled(),r.pushEnabled());return pref(preferences.save(p));}
 @Transactional public TemplateResponse create(TemplateRequest r){if(templates.existsByCodeIgnoreCase(r.code()))throw new ConflictException("Template code already exists");NotificationTemplate t=new NotificationTemplate(r.code(),r.channel(),r.subject(),r.body());if(!r.active())t.update(r.channel(),r.subject(),r.body(),false);return TemplateResponse.from(templates.save(t));}
 @Transactional public TemplateResponse update(UUID id,TemplateRequest r){NotificationTemplate t=templates.findById(id).orElseThrow(()->new NotFoundException("Template not found"));if(!t.getCode().equalsIgnoreCase(r.code()))throw new BadRequestException("Template code cannot be changed");t.update(r.channel(),r.subject(),r.body(),r.active());return TemplateResponse.from(t);}
 @Transactional(readOnly=true)public List<TemplateResponse>templates(){return templates.findAllByOrderByCodeAsc().stream().map(TemplateResponse::from).toList();}
 @Transactional public int broadcast(BroadcastRequest r){int count=0;for(User u:users.findAll())if(u.isActive()){notifications.save(new Notification(u,r.channel(),r.category(),r.subject(),r.message()));count++;}return count;}
 @Transactional public int dispatch(){List<Notification> batch=notifications.findTop100ByStatusOrderByCreatedAtAsc(NotificationStatus.QUEUED);for(Notification n:batch)n.sent("mock-"+UUID.randomUUID());return batch.size();}
 private User user(UUID id){return users.findById(id).orElseThrow(()->new UnauthorizedException("User not found"));}private static String money(long p){return java.math.BigDecimal.valueOf(p,2).toPlainString();}private static PreferenceResponse pref(NotificationPreference p){return new PreferenceResponse(p.getUserId(),p.isEmailEnabled(),p.isSmsEnabled(),p.isPushEnabled());}}
